style.css:
/* Abyssal Angel — Pastel Goth Nautical */
/* i really want this to be global */

:root {
  /* swap these colors whenever you like */
  --my-lavender: #c7b4dc;
  --my-pink: #e6b8cc;
  --my-seafoam: #b7d6d0;
  --my-ocean: #25283f;
  --my-cream: #f3eaf0;
  --my-ink: #49445b;
}

/* dreamy page backgrounds */
body {
  background: linear-gradient(
    145deg,
    #e8d9eb,
    #d5e8e3,
    #f3dce8
  ) !important;
  color: var(--my-ink) !important;
  font-family: Georgia, serif !important;
}

/* soft, gothic typography */
h1, h2, h3, h4 {
  color: var(--my-ocean) !important;
  font-family: Georgia, serif !important;
  letter-spacing: 1px !important;
}

/* dreamy ocean links */
a {
  color: #9475ae !important;
  text-decoration-color: var(--my-pink) !important;
  text-decoration-thickness: 1px !important;
  transition: color 0.2s ease !important;
}

a:hover {
  color: #b36f91 !important;
}

/* soften images */
img {
  border-radius: 12px !important;
}

/* pastel buttons */
button,
input[type="button"],
input[type="submit"] {
  background: var(--my-lavender) !important;
  color: #fff7fc !important;
  border: 1px solid var(--my-pink) !important;
  border-radius: 20px !important;
}

/* soft selection color */
::selection {
  background: var(--my-pink) !important;
  color: white !important;
}

/* delicate scrollbars */
::-webkit-scrollbar {
  width: 9px !important;
}

::-webkit-scrollbar-thumb {
  background: linear-gradient(
    var(--my-lavender),
    var(--my-seafoam)
  ) !important;
  border-radius: 20px !important;
}

::-webkit-scrollbar-track {
  background: #f3eaf0 !important;
}
